<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Avaliar pedido · <?= e($order['tenant_name']) ?></title><link rel="stylesheet" href="/assets/loja.css?v=20260903-turnstile1"><link rel="stylesheet" href="/assets/app.css?v=20260826-responsivo1"></head><body><main class="pagina-acompanhamento"><article class="cartao-acompanhamento" aria-labelledby="reviewTitle"><span class="sobretitulo"><?= e(strtoupper($order['tenant_name'])) ?></span><h1 id="reviewTitle">Avalie seu pedido</h1><p>Olá, <?= e($order['customer_name']) ?>. As avaliações são verificadas porque este acesso pertence a um pedido entregue.</p><?php if($flash):?><div class="aviso <?= e($flash[0]) ?>" role="<?= $flash[0]==='error'?'alert':'status' ?>"><?= e($flash[1]) ?></div><?php endif;?>
<?php foreach($items as$item):$reviewHeading='review-product-'.(int)$item['id'];?><section class="cartao-produto" aria-labelledby="<?= e($reviewHeading) ?>"><h2 id="<?= e($reviewHeading) ?>"><?= e($item['name']) ?></h2><?php if($item['review_id']):?><p>Você avaliou este produto com <b><?= (int)$item['rating'] ?>/5</b>.</p><?php if($item['comment']):?><p><?= e($item['comment']) ?></p><?php endif;?><?php else:?><form class="formulario" method="post" action="/avaliar/<?= e($token) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><label>Nota<select name="rating" required aria-label="Nota para <?= e($item['name']) ?>"><option value="5">5 — Excelente</option><option value="4">4 — Muito bom</option><option value="3">3 — Bom</option><option value="2">2 — Ruim</option><option value="1">1 — Muito ruim</option></select></label><label>Comentário<textarea name="comment" maxlength="1000" aria-describedby="reviewHelp"></textarea></label><?= turnstile_widget('product_review') ?><button class="botao primario" type="submit">Enviar avaliação</button></form><?php endif;?></section><?php endforeach;?>
<?php if($courier):?><section class="cartao-produto" aria-labelledby="courierReviewTitle"><h2 id="courierReviewTitle">Entrega por <?= e($courier['name']) ?></h2><?php if($courier['review_id']):?><p>Você avaliou a entrega com <b><?= (int)$courier['rating'] ?>/5</b>.</p><?php if($courier['comment']):?><p><?= e($courier['comment']) ?></p><?php endif;?><?php else:?><form class="formulario" method="post" action="/avaliar/<?= e($token) ?>/entrega"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>Nota<select name="rating" required aria-label="Nota para a entrega"><option value="5">5 — Excelente</option><option value="4">4 — Muito bom</option><option value="3">3 — Bom</option><option value="2">2 — Ruim</option><option value="1">1 — Muito ruim</option></select></label><label>Comentário<textarea name="comment" maxlength="1000" aria-describedby="reviewHelp"></textarea></label><?= turnstile_widget('courier_review') ?><button class="botao primario" type="submit">Avaliar entrega</button></form><?php endif;?></section><?php endif;?><small id="reviewHelp">Não inclua telefone, endereço, dados de pagamento ou outras informações pessoais no comentário.</small>
</article></main><?= turnstile_script() ?></body></html>

